import{_ as a,a0 as l,w as d,s as p,I as s,x as t,a1 as i,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"以單用户模式啓動 CentOS/RHEL 7/8 的三種方法 | LCTT x X-CMD","titleTemplate":false,"description":"以單用户模式啓動 CentOS/RHEL 7/8 的三種方法 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"以單用户模式啓動 CentOS/RHEL 7/8 的三種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"以單用户模式啓動 CentOS/RHEL 7/8 的三種方法 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode","title":"以單用户模式啓動 CentOS/RHEL 7/8 的三種方法","tag":"202005","desc":""},"relativePath":"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode.md","filePath":"[post].md"}'),g={name:"202005/20200430 Three Methods Boot CentOS-RHEL 7-8 Systems in Single User Mode.md"};function h(u,e,c,b,k,m){const o=l("Link");return d(),p("div",null,[e[27]||(e[27]=s("h1",{id:"以單用户模式啓動-centos-rhel-7-8-的三種方法",tabindex:"-1"},[t("以單用户模式啓動 CentOS/RHEL 7/8 的三種方法 "),s("a",{class:"header-anchor",href:"#以單用户模式啓動-centos-rhel-7-8-的三種方法","aria-label":"Permalink to “以單用户模式啓動 CentOS/RHEL 7/8 的三種方法”"},"​")],-1)),e[28]||(e[28]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/03/230109uw1f9zvv9upbhwv8.jpg",alt:""})],-1)),e[29]||(e[29]=s("p",null,"單用户模式，也被稱為維護模式，超級用户可以在此模式下恢復/修復系統問題。",-1)),e[30]||(e[30]=s("p",null,"通常情況下，這類問題在多用户環境中修復不了。系統可以啓動但功能不能正常運行或者你登錄不了系統。",-1)),s("p",null,[e[1]||(e[1]=t("在基於 ",-1)),i(o,{href:"https://www.2daygeek.com/category/red-hat/"},{default:n(()=>[...e[0]||(e[0]=[t("Red Hat",-1)])]),_:1}),e[2]||(e[2]=t("（RHEL）7/8 的系統中，使用 ",-1)),e[3]||(e[3]=s("code",null,"runlevel1.target",-1)),e[4]||(e[4]=t(" 或 ",-1)),e[5]||(e[5]=s("code",null,"rescue.target",-1)),e[6]||(e[6]=t(" 來實現。",-1))]),e[31]||(e[31]=s("p",null,"在此模式下，系統會掛載所有的本地文件系統，但不開啓網絡接口。",-1)),e[32]||(e[32]=s("p",null,"系統僅啓動特定的幾個服務和修復系統必要的儘可能少的功能。",-1)),e[33]||(e[33]=s("p",null,"當你想運行文件系統一致性檢查來修復損壞的文件系統，或忘記 root 密碼後重置密碼，或要修復系統上的一個掛載點問題時，這個方法會很有用。",-1)),s("p",null,[e[9]||(e[9]=t("你可以用下面三種方法以單用户模式啓動 ",-1)),i(o,{href:"https://www.2daygeek.com/category/centos/"},{default:n(()=>[...e[7]||(e[7]=[t("CentOS",-1)])]),_:1}),e[10]||(e[10]=t("/",-1)),i(o,{href:"https://www.2daygeek.com/category/rhel/"},{default:n(()=>[...e[8]||(e[8]=[t("RHEL",-1)])]),_:1}),e[11]||(e[11]=t(" 7/8 系統。",-1))]),e[34]||(e[34]=r('<ul><li>方法 1：通過向內核添加 <code>rd.break</code> 參數來以單用户模式啓動 CentOS/RHEL 7/8 系統</li><li>方法 2：通過用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替換內核中的 <code>rhgb quiet</code> 語句來以單用户模式啓動 CentOS/RHEL 7/8 系統</li><li>方法 3：通過用 <code>rw init=/sysroot/bin/sh</code> 參數替換內核中的 <code>ro</code> 語句以單用户模式啓動 CentOS/RHEL 7/8 系統</li></ul><h3 id="方法-1" tabindex="-1">方法 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1”">​</a></h3><p>通過向內核添加 <code>rd.break</code> 參數來以單用户模式啓動 CentOS/RHEL 7/8 系統。</p><p>重啓你的系統，在 GRUB2 啓動界面，按下 <code>e</code> 鍵來編輯選中的內核。你需要選中第一行，第一個是最新的內核，然而如果你想用舊的內核啓動系統你也可以選擇其他的行。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-2.png" alt=""></p><p>根據你的 RHEL/CentOS 版本，找到 <code>linux16</code> 或 <code>linux</code> 語句，按下鍵盤上的 <code>End</code> 鍵，跳到行末，像下面截圖中展示的那樣添加關鍵詞 <code>rd.break</code>，按下 <code>Ctrl+x</code> 或 <code>F10</code> 來進入單用户模式。</p><p>如果你的系統是 RHEL/CentOS 7，你需要找 <code>linux16</code>，如果你的系統是 RHEL/CentOS 8，那麼你需要找 <code>linux</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-3.png" alt=""></p><p>這個修改會讓你的 root 文件系統以 “只讀（<code>ro</code>）” 模式掛載。你可以用下面的命令來驗證下。下面的輸出也明確地告訴你當前是在 “<ruby>緊急模式<rt>Emergency Mode</rt></ruby>”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount | grep root</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-5.png" alt=""></p><p>為了修改 <code>sysroot</code> 文件系統，你需要用讀寫模式（<code>rw</code>）重新掛載它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /sysroot</span></span></code></pre></div><p>運行下面的命令修改環境，這就是大家熟知的 “監禁目錄” 或 “chroot 監獄”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /sysroot</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-8.png" alt=""></p><p>現在，單用户模式已經完全準備好了。當你修復了你的問題要退出單用户模式時，執行下面的步驟。</p><p>CentOS/RHEL 7/8 默認使用 SELinux，因此創建下面的隱藏文件，這個文件會在下一次啓動時重新標記所有文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最後，用下面的命令重啓系統。你也可以輸入兩次 <code>exit</code> 命令來重啓你的系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -f</span></span></code></pre></div><h3 id="方法-2" tabindex="-1">方法 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2”">​</a></h3><p>通過用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替換內核中的 <code>rhgb quiet</code> 語句來以單用户模式啓動 CentOS/RHEL 7/8 系統。</p><p>重啓你的系統，在 GRUB2 啓動界面，按下 <code>e</code> 鍵來編輯選中的內核。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/reset-forgotten-root-password-on-rhel-7-centos-7-2.png" alt=""></p><p>找到語句 <code>rhgb quiet</code>，用 <code>init=/bin/bash</code> 或 <code>init=/bin/sh</code> 替換它，然後按下 <code>Ctrl+x</code> 或 <code>F10</code> 來進入單用户模式。</p><p><code>init=/bin/bash</code> 的截圖。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-1.png" alt=""></p><p><code>init=/bin/sh</code> 的截圖。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-1a.png" alt=""></p><p>默認情況下，上面的操作會以只讀（<code>ro</code>）模式掛載你的 <code>/</code> 分區，因此你需要以讀寫（<code>rw</code>）模式重新掛載 <code>/</code> 文件系統，這樣才能修改它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/12/method-reset-forgotten-root-password-on-rhel-7-centos-7-4.png" alt=""></p><p>現在你可以執行你的任務了。當結束時，執行下面的命令來開啓重啓時的 SELinux 重新標記。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最後，重啓系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># exec /sbin/init 6</span></span></code></pre></div><h3 id="方法-3" tabindex="-1">方法 3 <a class="header-anchor" href="#方法-3" aria-label="Permalink to “方法 3”">​</a></h3><p>通過用 <code>rw init=/sysroot/bin/sh</code> 參數替換內核中的 <code>ro</code> 單詞，以單用户模式啓動 CentOS/RHEL 7/8 系統。</p><p>為了中斷自動啓動的過程，重啓你的系統並在 GRUB2 啓動界面按下任意鍵。</p><p>現在會展示你係統上所有可用的內核，選擇最新的內核，按下 <code>e</code> 鍵來編輯選中的內核參數。</p><p>找到以 <code>linux</code> 或 <code>linux16</code> 開頭的語句，用 <code>rw init=/sysroot/bin/sh</code> 替換 <code>ro</code>。替換完後按下 <code>Ctrl+x</code> 或 <code>F10</code> 來進入單用户模式。</p><p>運行下面的命令把環境切換為 “chroot 監獄”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /sysroot</span></span></code></pre></div><p>如果需要，做出必要的修改。修改完後，執行下面的命令來開啓重啓時的 SELinux 重新標記。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># touch /.autorelabel</span></span></code></pre></div><p>最後，重啓系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -f</span></span></code></pre></div><hr>',49)),s("p",null,[e[13]||(e[13]=t("via: ",-1)),i(o,{href:"https://www.2daygeek.com/boot-centos-7-8-rhel-7-8-single-user-mode/"},{default:n(()=>[...e[12]||(e[12]=[t("https://www.2daygeek.com/boot-centos-7-8-rhel-7-8-single-user-mode/",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("作者：",-1)),i(o,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...e[14]||(e[14]=[t("Magesh Maruthamuthu",-1)])]),_:1}),e[19]||(e[19]=t(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 譯者：",-1)),i(o,{href:"https://github.com/lxbwolf"},{default:n(()=>[...e[16]||(e[16]=[t("lxbwolf",-1)])]),_:1}),e[21]||(e[21]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[24]||(e[24]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...e[23]||(e[23]=[t("Linux中國",-1)])]),_:1}),e[26]||(e[26]=t(" 榮譽推出",-1))])])}const C=a(g,[["render",h]]);export{y as __pageData,C as default};
